<?php require __DIR__.'/config.php';require_login();$q=db()->prepare('SELECT * FROM videos WHERE user_id=? ORDER BY created_at DESC');$q->execute([current_user()['id']]);$videos=$q->fetchAll();require __DIR__.'/includes/header.php';?><div class="listing"><h2>My Videos</h2><div class="video-grid"><?php foreach($videos as $v):?><div class="video-cell"><a href="watch.php?id=<?=$v['id']?>"><img class="video-thumb" src="<?=h(video_thumb($v))?>" alt=""><?=h($v['title'])?></a></div><?php endforeach;?><?php if(!$videos):?><p class="empty">You have not uploaded any videos yet.</p><?php endif;?></div><p class="center"><a href="upload.php">Upload Videos</a></p></div><?php require __DIR__.'/includes/footer.php';?>
